package sa.abroj.baseersms.v2;
import android.Manifest; import android.content.Context; import android.content.pm.PackageManager; import android.database.Cursor; import android.provider.Telephony; import androidx.work.Data; import androidx.work.ExistingWorkPolicy; import androidx.work.OneTimeWorkRequest; import androidx.work.WorkManager; import androidx.work.Worker; import androidx.work.WorkerParameters;
/** User-selected inbox import. The provider row ID makes overlapping ranges idempotent. */
public final class HistoricalImportWorker extends Worker {
 private static final String START="start",END="end"; public HistoricalImportWorker(Context c,WorkerParameters p){super(c,p);} static void enqueue(Context c,long start,long end){Data in=new Data.Builder().putLong(START,start).putLong(END,end).build();WorkManager.getInstance(c).enqueueUniqueWork("baseer-sms-v2-history",ExistingWorkPolicy.KEEP,new OneTimeWorkRequest.Builder(HistoricalImportWorker.class).setInputData(in).build());}
 @Override public Result doWork(){Context c=getApplicationContext();if(!SecureSettings.isPaired(c)||c.checkSelfPermission(Manifest.permission.READ_SMS)!=PackageManager.PERMISSION_GRANTED)return Result.failure();long start=getInputData().getLong(START,0),end=getInputData().getLong(END,0);if(start<1||end<=start)return Result.failure();int added=0,duplicates=0;String[] cols={Telephony.Sms._ID,Telephony.Sms.ADDRESS,Telephony.Sms.BODY,Telephony.Sms.DATE};try(Cursor rows=c.getContentResolver().query(Telephony.Sms.Inbox.CONTENT_URI,cols,"date >= ? AND date < ?",new String[]{Long.toString(start),Long.toString(end)},"date ASC, _id ASC")){if(rows==null)return Result.retry();SmsOutbox outbox=new SmsOutbox(c);while(rows.moveToNext()){String sender=rows.getString(1),body=rows.getString(2);if(sender==null||body==null||body.isEmpty())continue;String token="history:"+SecureSettings.code(c)+":"+rows.getLong(0);if(outbox.capture(sender,body,rows.getLong(3),token))added++;else duplicates++;}StatusStore.error(c,"");SyncWorker.enqueue(c);return Result.success();}catch(SecurityException e){return Result.failure();}catch(Exception e){StatusStore.error(c,"history_import_retry");return Result.retry();}}
}
